        <div class="notification-list">@forelse($notifications as $notification)<article class="notification-item severity-{{ $notification->severity }} {{ $notification->read_at?'is-read':'' }}" wire:key="notification-{{ $notification->id }}"><span class="notification-signal"></span><div><div class="notification-meta"><strong>{{ $notification->title }}</strong><time>{{ $notification->created_at->diffForHumans() }}</time></div><p>{{ $notification->message }}</p><small>{{ ['danger'=>'حرج','warning'=>'مهم','info'=>'معلومة'][$notification->severity]??'تنبيه' }} · {{ $notification->read_at?'مقروء':'غير مقروء' }}</small></div><div class="notification-actions"><a class="ghost-button" href="{{ $notification->targetUrl() }}" wire:navigate>عرض العنصر</a>@unless($notification->read_at)<button type="button" class="ghost-button" wire:click="markRead({{ $notification->id }})">تمت القراءة</button>@endunless</div></article>@empty<div class="empty-state"><span>✓</span><strong>كل شيء هادئ</strong><small>لا توجد تنبيهات ضمن هذا الفلتر.</small></div>@endforelse</div>{{ $notifications->links() }}</section>
